class FEMultiMenu {
    char layout[0x15c];
public:
    virtual ~FEMultiMenu();
};

class TextString {
public:
    virtual ~TextString();
};

class NameEntryMenu {
public:
    virtual ~NameEntryMenu();
};

class HighScoreFrontEnd : public FEMultiMenu {
    void* sys;
    TextString* column_labels[5];
    TextString* info[10][5];
    void* arrows[2][2];
    void* line;
    int arrow_counter;
    int arrow_num;
    unsigned int labelColor;
    bool in_game;
    float flash_timer;
    int next_menu;
    void* all_beaches[28 * 2];
    NameEntryMenu* nem;
    void* fade;
    void* lines[19];
    int first_line;
    int second_line;
public:
    virtual ~HighScoreFrontEnd();
};

HighScoreFrontEnd::~HighScoreFrontEnd()
{
    for(int i=0; i<5; i++)
    {
        for(int j=0; j<10; j++)
            delete info[j][i];
        delete column_labels[i];
    }

    delete nem;
}
